<?php
require_once __DIR__.'/portal.php';
function rmmc_staff_attendance(string $role): void {
    rmmc_require_roles($role);
    $search=trim((string)($_GET['search']??''));$event=(int)($_GET['event']??0);
    $status=(string)($_GET['status']??'');if(!in_array($status,['Present','Absent','Incomplete','Pending'],true))$status='';
    $where=['1=1'];$params=[];$types='';
    if($search!==''){$where[]='(s.student_number LIKE ? OR s.firstname LIKE ? OR s.lastname LIKE ?)';$v='%'.$search.'%';array_push($params,$v,$v,$v);$types.='sss';}
    if($event){$where[]='a.event_id=?';$params[]=$event;$types.='i';}
    if($status!==''){$where[]='a.status=?';$params[]=$status;$types.='s';}
    $where=implode(' AND ',$where);
    $rows=rmmc_all("SELECT a.*,s.student_number,s.firstname,s.lastname,s.course,s.year_level,e.title FROM attendance a JOIN students s ON a.student_id=s.id JOIN events e ON a.event_id=e.id WHERE $where ORDER BY a.date DESC LIMIT 150",$types,$params);
    $events=rmmc_all('SELECT id,title FROM events ORDER BY event_date DESC LIMIT 150');
    rmmc_shell_start('Attendance',$role);
    ?><div class="welcome"><h1>Attendance records</h1><p>Review attendance by student and event. Separate QR scans are stored in the scan log.</p></div><section class="panel"><form method="get" class="filters"><div class="field"><label>Student name or ID</label><input name="search" value="<?=rmmc_e($search)?>"></div><div class="field"><label>Event</label><select name="event"><option value="0">All events</option><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>" <?=$event===(int)$e['id']?'selected':''?>><?=rmmc_e($e['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['Present','Absent','Incomplete','Pending'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><button>Search</button></form><div class="table-scroll"><table class="data-table"><tr><th>Student</th><th>Course / Year</th><th>Event</th><th>Date</th><th>AM In</th><th>AM Out</th><th>PM In</th><th>PM Out</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><a href="student_view.php?id=<?=(int)$r['student_id']?>"><?=rmmc_e($r['lastname'].', '.$r['firstname'])?></a><br><small><?=rmmc_e($r['student_number'])?></small></td><td><?=rmmc_e($r['course'])?> / <?=rmmc_e($r['year_level'])?></td><td><?=rmmc_e($r['title'])?></td><td><?=rmmc_e($r['date'])?></td><td><?=rmmc_e($r['morning_in']?:'—')?></td><td><?=rmmc_e($r['morning_out']?:'—')?></td><td><?=rmmc_e($r['afternoon_in']?:'—')?></td><td><?=rmmc_e($r['afternoon_out']?:'—')?></td><td><?=rmmc_badge($r['status'])?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="empty">No attendance results found.</p><?php endif;?></section><?php rmmc_shell_end();
}
function rmmc_student_attendance():void {
    rmmc_require_roles('Student');$s=rmmc_student();if(!$s){http_response_code(404);exit('No student profile');}
    $rows=rmmc_all('SELECT a.*,e.title,e.organizer,e.is_required FROM attendance a JOIN events e ON a.event_id=e.id WHERE a.student_id=? ORDER BY a.date DESC LIMIT 150','i',[(int)$s['id']]);
    $scans=rmmc_table_exists('ite_attendance_scans')?rmmc_all('SELECT t.*,e.title FROM ite_attendance_scans t JOIN events e ON t.event_id=e.id WHERE t.student_id=? ORDER BY t.scanned_at DESC LIMIT 100','i',[(int)$s['id']]):[];
    rmmc_shell_start('My Attendance','Student'); ?><div class="welcome"><h1>My attendance history</h1><p>Your event-specific attendance status and recorded QR scans. Not-required sessions do not count as absences.</p></div><section class="panel"><h2>Event attendance</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Date</th><th>Morning In</th><th>Morning Out</th><th>Afternoon In</th><th>Afternoon Out</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=rmmc_e($r['title'])?></td><td><?=rmmc_e($r['date'])?></td><td><?=rmmc_e($r['morning_in']?:'—')?></td><td><?=rmmc_e($r['morning_out']?:'—')?></td><td><?=rmmc_e($r['afternoon_in']?:'—')?></td><td><?=rmmc_e($r['afternoon_out']?:'—')?></td><td><?=rmmc_badge($r['status'])?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="empty">No event attendance yet.</p><?php endif;?></section><section class="panel"><h2>Individual QR scans</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Date</th><th>Attendance slot</th><th>Recorded time</th></tr><?php foreach($scans as $r):?><tr><td><?=rmmc_e($r['title'])?></td><td><?=rmmc_e($r['session_date'])?></td><td><?=rmmc_e(ucwords(str_replace('_',' ',$r['slot'])))?></td><td><?=rmmc_e($r['scanned_at'])?></td></tr><?php endforeach;?></table></div><?php if(!$scans):?><p class="empty">No individual scans recorded.</p><?php endif;?></section><?php rmmc_shell_end();
}
function rmmc_scanner(string $role):void {
    rmmc_require_roles($role);
    $events=rmmc_all('SELECT * FROM events WHERE status = ? ORDER BY event_date DESC','s',['Ongoing']);
    rmmc_shell_start('QR Scanner',$role);
    ?><div class="welcome"><h1>Scan student attendance QR</h1><p>Select the event and one attendance slot. Each scan records only that slot.</p></div><section class="columns"><div class="panel"><div class="field"><label for="event">Ongoing event</label><select id="event" required><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>"><?=rmmc_e($e['title'].' · '.$e['event_date'])?></option><?php endforeach;?></select></div><div class="field" style="margin:14px 0"><label for="slot">Attendance slot</label><select id="slot"><option value="morning_in">Morning Time In</option><option value="morning_out">Morning Time Out</option><option value="afternoon_in">Afternoon Time In</option><option value="afternoon_out">Afternoon Time Out</option></select></div><div class="row"><button id="start" <?=!$events?'disabled':''?>>Start camera</button><button id="stop" class="ghost">Stop</button></div><video id="video" playsinline muted autoplay style="width:100%;max-height:290px;border-radius:13px;margin:14px 0;background:#111"></video><p class="small">Camera access generally requires HTTPS or localhost. On <code>http://rmmc-ite.local</code>, browsers may block it. A USB QR scanner can use the input on the right.</p></div><div class="panel"><h2>Scan result</h2><div id="result" class="notice" aria-live="polite">Ready to scan.</div><form id="manual"><div class="field"><label for="qr">USB scanner input / QR token</label><input id="qr" autocomplete="off" placeholder="Scan code here"></div><button style="margin-top:12px" <?=!$events?'disabled':''?>>Record scan</button></form><?php if(!$events):?><p class="notice">No ongoing events. Set an event to Ongoing before scanning.</p><?php endif;?></div></section><script>
let media=null,detector=null,scanning=false,busy=false;const output=document.getElementById('result'),video=document.getElementById('video'),token=document.getElementById('qr');const csrf=<?=json_encode(rmmc_csrf())?>;
async function submitScan(value){if(busy||!value.trim())return;busy=true;output.textContent='Validating QR and recording attendance…';try{const b=new URLSearchParams({csrf,event_id:document.getElementById('event').value,slot:document.getElementById('slot').value,qr:value.trim()});const response=await fetch('process_attendance.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b,credentials:'same-origin'});const data=await response.json();output.className='notice '+(response.ok?'success':'error');output.textContent=data.message||'Unable to record attendance';if(response.ok){stopCamera();token.value='';}}catch(e){output.className='notice error';output.textContent='Network or server error. No attendance confirmation received.';}finally{busy=false;}}
async function startCamera(){if(!('BarcodeDetector'in window)){output.textContent='This browser does not support built-in QR scanning. Use a compatible browser or a USB QR reader.';return;}if(!navigator.mediaDevices?.getUserMedia){output.textContent='Camera unavailable. Use HTTPS / localhost or the USB scanner input.';return;}try{detector=new BarcodeDetector({formats:['qr_code']});media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});video.srcObject=media;await video.play();scanning=true;scanLoop();output.textContent='Camera is ready. Point it at a student QR code.';}catch(e){output.textContent='Camera unavailable or permission denied: '+e.message;}}
async function scanLoop(){if(!scanning)return;if(!busy){try{for(const hit of await detector.detect(video)){if(hit.rawValue){await submitScan(hit.rawValue);break;}}}catch(e){}}if(scanning)requestAnimationFrame(scanLoop)}function stopCamera(){scanning=false;media?.getTracks().forEach(t=>t.stop());media=null;video.srcObject=null;}
document.getElementById('start').onclick=startCamera;document.getElementById('stop').onclick=stopCamera;document.getElementById('manual').addEventListener('submit',e=>{e.preventDefault();submitScan(token.value);});window.addEventListener('pagehide',stopCamera);
</script><?php rmmc_shell_end();
}
